-- Preserve the approved IPO/PT v4 renderers alongside the original immutable archive.
-- No document, master, rate, rule or historical archive is changed.
INSERT INTO document_format_archives(version,fingerprint,payload) VALUES(2,'04127436be5062524a517359b8a7502eb80bbd580c7f009f7b8e98aa8919931b',$approved_ipo_pt${"label":"Director-approved IPO and PT layout v4, preserved 15 October 2026","documentLayoutVersion":4,"historicalArchiveVersion":1,"files":{"server/orders/report-v4.ts":"import { displayUnit } from \"../boq/unit.js\";\nimport { appendPeachtreePage } from \"./peachtree-report-v4.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport { ipoPresentation } from \"./presentation.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport {\n  drawReportLogo,\n  drawReportFooter,\n  reportBottomMargin,\n} from \"../reports/branding.js\";\nconst clean = (s: unknown) =>\n  String(s ?? \"\")\n    .replaceAll(\"\u00d7\", \"x\")\n    .replace(/[\u2013\u2014]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nexport function buildIpoPdf(s: any, number?: string, division = s.peachtree, options:{includePt?:boolean}={}) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: number ?? \"Draft IPO\",\n    author: \"Power Zone Engineering & Services\",\n  });\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\n    number ? \"INTERNAL PURCHASE ORDER\" : \"DRAFT INTERNAL PURCHASE ORDER\",\n    14,\n    37,\n  );\n  pdf.setFontSize(8);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 42);\n  const i = s.input;\n  const view = ipoPresentation({\n    ...s,\n    quotationType: division ?? s.quotationType,\n  });\n  const taxDeal=s.quotationType?.saleType !== \"Cash Deal\";\n  const entries = [\n    [\"IPO / Job reference\",number ?? \"DRAFT\",\"Quotation reference\",s.quotationNumber || \"Not available\"],\n    [\"Company to invoice\",i.invoiceCompany,\"Tax deal\",taxDeal?\"Yes\":\"No\"],\n    [\"Prepared by\",\"Atif\",\"Checked by\",\"Atif\"],\n    [\"Customer\",s.customer.name,\"Site / branch\",`${s.siteName ?? \"Not entered\"} / ${s.siteCode ?? \"Not entered\"}`],\n    [\"Customer PO / approval\",i.poNumber || i.evidenceNotes || \"Not entered\",\"PO / approval date\",i.orderDate],\n    ...(taxDeal?[[\"Customer NTN\",i.customerNtn || \"Not entered\",\"Customer STRN\",i.customerStrn || \"Not entered\"]]:[]),\n    [\"Billing address\",i.billingAddress || \"Not entered\",\"Customer contact\",`${i.contactPerson || s.customer.contactPerson || \"Not entered\"} / ${i.phone || s.customer.phone || \"Not entered\"}`],\n  ];\n  autoTable(pdf, {\n    startY: 46,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.4 },\n    columnStyles: {\n      0: { cellWidth: 27 },\n      1: { cellWidth: 64 },\n      2: { cellWidth: 27 },\n      3: { cellWidth: 64 },\n    },\n    body: [\n      ...entries,\n      [\"Quotation type\", quotationTypeLabel(division ?? s), \"\", \"\"],\n    ].map((row) => row.map(clean)),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 4,\n    theme: \"grid\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 7, cellPadding: 1.3 },\n    headStyles: { fillColor: [61, 63, 146], fontSize: 7 },\n    head: [[\"Description\", \"Qty\", \"Unit\", view.included ? \"Rate\" : \"Rate excl. GST\", view.included ? \"Amount\" : \"Amount excl. GST\"]],\n    columnStyles: {0:{cellWidth:100},1:{halign:\"center\",cellWidth:10},2:{halign:\"center\",cellWidth:12},3:{halign:\"right\"},4:{halign:\"right\"}},\n    body:view.rows.map(l=>[clean(l.description)+(/solar|panel/i.test(l.description)?' - Revise at IRR stage.':''),l.qty,displayUnit(l.unit,l.qty),money(l.rate),money(l.amount)]),\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 3,\n    theme: \"plain\",\n    margin: { left: 14, right: 14, bottom: reportBottomMargin },\n    styles: { fontSize: 8, cellPadding: 1.2 },\n    body: [\n      ...(!view.included\n        ? [\n            [\"Grand total before tax\", {content:money(view.amount),styles:{halign:\"right\" as const}}],\n            ...view.taxSummary.filter(tax=>s.allocation.policy!==\"fixed-bank-ups\"||Number(tax.amount)!==0).map((tax)=>[tax.label,{content:money(tax.amount),styles:{halign:\"right\" as const}}]),\n          ]\n        : []),\n      [\"GRAND TOTAL (PKR)\", {content:money(s.allocation.total),styles:{halign:\"right\",fontStyle:\"bold\"}}],\n      ...(i.paymentMode ? [[\"Payment mode\", clean(i.paymentMode)]] : []),\n      ...(i.salesSource ? [[\"Sales source\", clean(i.salesSource)]] : []),\n      ...(i.remarks ? [[\"Remarks\", clean(i.remarks)]] : []),\n      ...(view.rows.some(r=>/solar|panel/i.test(r.description)) ? [[\"Panel wattage\", \"To be confirmed from IRR.\"]] : []),\n    ],\n  });\n  if (division && options.includePt!==false) appendPeachtreePage(pdf, s, division, number ?? \"DRAFT IPO\");\n  drawReportFooter(\n    pdf,\n    number\n      ? `${number} / IPO & Peachtree Division`\n      : \"DRAFT IPO & Peachtree Division\",\n  );\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/peachtree-report-v4.ts":"import {CASH_PROFIT_NOTE, retainedGst} from \"../commercial/deal.js\";\nimport {Decimal} from \"decimal.js\";\nimport { jsPDF } from \"jspdf\";\nimport { autoTable } from \"jspdf-autotable\";\nimport { drawReportLogo, drawReportFooter, reportBottomMargin } from \"../reports/branding.js\";\nimport { quotationTypeLabel } from \"./sale-type.js\";\nimport type { peachtreeDivision } from \"./peachtree.js\";\nimport {ptDisplayRows} from './pt-detail.js';\nconst money = (s: string) =>\n  Number(s).toLocaleString(\"en-PK\", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\nconst text = (v: unknown) =>\n  String(v ?? \"\")\n    .replace(/[\u2013\u2014]/g, \"-\")\n    .replace(/[^\\n\\x20-\\x7e\\xa0-\\xff]/g, \"\");\nexport function appendPeachtreePage(\n  pdf: jsPDF,\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  pdf.addPage();\n  drawReportLogo(pdf);\n  pdf.setFontSize(12);\n  pdf.text(\"PEACHTREE DIVISION\", 14, 38);\n  pdf.setFontSize(9);\n  pdf.text(\"POWER ZONE ENGINEERING & SERVICES (PVT) LIMITED\", 14, 44);\n  autoTable(pdf, {\n    startY: 50,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    body: [\n      [\"IPO\", number],\n      [\"Quotation\", text(s.quotationNumber)],\n      [\"BOQ\", text(s.boqNumber)],\n      [\"Customer\", text(s.customer.name)],\n      [\"Entry basis\", d.basis],\n      [\"Quotation type\", text(quotationTypeLabel(d))],\n    ],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 7,\n    theme: \"grid\",\n    headStyles: { fillColor: [61, 63, 146] },\n    footStyles: { fillColor: [61, 63, 146] },\n    margin:{left:14,right:14,bottom:reportBottomMargin},\n    styles: { fontSize: 8, cellPadding: 2.3 },\n    columnStyles: {0:{cellWidth:26},1:{cellWidth:37},2:{cellWidth:81},3:{halign:\"right\",cellWidth:38}},\n    head: [[\"PT phase\", \"Item ID\", \"Description / quantity\", d.saleType === \"Cash Deal\" ? \"Selling value (PKR)\" : \"Selling excl. GST (PKR)\"]],\n    body: ptDisplayRows(d).map((p:any)=>[p.name,text(p.itemId||'Not allocated'),text(p.description || \"Description not recorded\"),money(p.amount)]),\n    foot: [[\"PHASE TOTAL\",\"\",\"\", {content:money(d.phaseTotal),styles:{halign:\"right\"}}]],\n  });\n  autoTable(pdf, {\n    startY: (pdf as any).lastAutoTable.finalY + 6,\n    theme: \"plain\",\n    styles: { fontSize: 9, cellPadding: 2 },\n    columnStyles: { 1: { halign: \"right\" } },\n    body:\n      d.version >= 2 && d.taxMode === \"Tax Included\"\n        ? [[\"IPO payable\", money(d.ipoPayable)]]\n        : [\n            [\"IPO total before tax\", money(d.ipoBeforeTax)],\n            [\"IPO tax (separate reconciliation)\", money(d.ipoTax)],\n            [\"IPO payable\", money(d.ipoPayable)],\n          ],\n  });\n  const policy = d.policy === \"fixed-bank-ups-proportional-cost\" ? \"Approved UPS selling value excluding GST is allocated proportionally to the frozen component and installation costs. Accepted payable and GST remain unchanged.\" : \"EPC excludes the separately shown Earthing, Electrical Labour and Deliveries. Allocation uses saved BOQ category costs; accepted totals and GST remain unchanged.\";\n  pdf.setFontSize(8);\n  pdf.setFont('helvetica','normal');\n  pdf.text(\n    pdf.splitTextToSize(\n      text(\n        `${policy} ${retainedGst(d)?CASH_PROFIT_NOTE:\"GST is excluded from profit.\"}`,\n      ),\n      180,\n    ),\n    14,\n    (pdf as any).lastAutoTable.finalY + 5,\n  );\n}\nexport function buildPeachtreePdf(\n  s: any,\n  d: ReturnType<typeof peachtreeDivision>,\n  number: string,\n) {\n  const pdf = new jsPDF({ unit: \"mm\", format: \"a4\", compress: true });\n  pdf.setProperties({\n    title: `${number} - Peachtree Division`,\n    author: \"Power Zone Engineering & Services\",\n  });\n  appendPeachtreePage(pdf, s, d, number);\n  pdf.deletePage(1);\n  drawReportFooter(pdf, `${number} / Peachtree Division`);\n  return Buffer.from(pdf.output(\"arraybuffer\"));\n}\n","server/orders/document-renderers.ts":"import {buildIpoPdf as originalIpo} from './report.js';\nimport {buildPeachtreePdf as originalPt} from './peachtree-report.js';\nimport {buildIpoPdf as currentIpo} from './report-v4.js';\nimport {buildPeachtreePdf as currentPt} from './peachtree-report-v4.js';\n// Historical snapshots retain their original archived renderer.\nexport const buildIpoPdf=(s:any,number?:string,division=s.peachtree,options:{includePt?:boolean}={})=>s.documentLayoutVersion>=4?currentIpo(s,number,division,options):originalIpo(s,number,division);\nexport const buildPeachtreePdf=(s:any,d:any,number:string)=>s.documentLayoutVersion>=4?currentPt(s,d,number):originalPt(s,d,number);\n"},"sha256":{"server/orders/report-v4.ts":"381d4eafbec4a3d60473449d9412b04fd2750a65cc65b7b7bfc75a0a5e537df1","server/orders/peachtree-report-v4.ts":"720a5f7e287d4487fa878aad9a941ea979158d02b438d86598feca232bb8a460","server/orders/document-renderers.ts":"511e21e6d976229b1b02f676704c204ce11488aaa1c3fcb03673b08750ff6539"}}$approved_ipo_pt$::jsonb);
